const D = { folds: 8, energy: .75, scale: 1, density: .55, speed: 1, hue: 0, x: .5, y: .5, style: 'cathedral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// coarse buffer, upscaled
const BW = 180, BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const sd = (P.seed | 0);
const JH = [350, 225, 150, 45, 285, 190, 330, 262];
function jhue(id) { let h = (id * 2654435761) >>> 0; h ^= h >> 15; h = (h * 668265263) >>> 0; return JH[h % JH.length]; }
function hsb2rgb(h, s, v) {
  h = ((h % 360) + 360) % 360;
  const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, gg, b; const hi = Math.floor(h / 60) % 6;
  if (hi === 0) { r = c; gg = x; b = 0; } else if (hi === 1) { r = x; gg = c; b = 0; }
  else if (hi === 2) { r = 0; gg = c; b = x; } else if (hi === 3) { r = 0; gg = x; b = c; }
  else if (hi === 4) { r = x; gg = 0; b = c; } else { r = c; gg = 0; b = x; }
  return [r + m, gg + m, b + m];
}

const style = P.style;
const N = Math.max(4, Math.min(24, Math.round(P.folds)));
const aspect = BW / BH;
const cx = P.x, cy = P.y;
// motion floor: continuous rotation + drifting backlight spot (never re-phases, no strobe)
const rot = K.t * (0.016 + P.speed * 0.032);
const spotx = Math.cos(K.t * (0.11 + P.speed * 0.05)) * 0.24;
const spoty = Math.sin(K.t * (0.14 + P.speed * 0.05)) * 0.24;
const Rout = 0.72 * P.scale;
const expo = 0.5 + P.energy * 0.95 + K.intensity * 0.25 + A.bass * 0.55;
const glassThresh = 0.70 + P.density * 0.17;   // higher density = thinner leading
const secHue = K.section * 20 + K.t * 0.35;

// scratch cell math (closure over rr/th so no per-pixel allocation)
let rr = 0, th = 0;
const TMP = { d: 0, li: 0 };
function cell(r0, r1, lobes, wa) {
  const rf = (rr - r0) / (r1 - r0);
  const ca = 6.2831853 / lobes;
  let la = th % ca; if (la < 0) la += ca;
  TMP.li = Math.floor(th / ca);
  la = (la / ca) * 2 - 1;
  const ro = rf * 2 - 1;
  TMP.d = Math.sqrt(la * la * wa + ro * ro / wa);
  return TMP;
}

for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    const ux = (i / BW - cx) * aspect;
    const uy = (j / BH - cy);
    const r = Math.sqrt(ux * ux + uy * uy);
    rr = r / Rout;
    th = Math.atan2(uy, ux) + rot;

    // backlight: soft radial core + drifting off-centre spot (breaks symmetry so it never re-phases)
    const dspot = Math.sqrt((ux - spotx) * (ux - spotx) + (uy - spoty) * (uy - spoty));
    const back = (0.5 + 0.62 * Math.exp(-r * 1.7)) * (0.72 + 0.68 * Math.exp(-dspot * 2.3));

    let kind = 0;      // 0 ambient/stone, 1 glass, 2 leading line
    let cid = 0, dcell = 1;

    if (rr < 0.14) { const q = cell(0.0, 0.14, N, 1.0); dcell = q.d; cid = 131 + q.li + sd * 7; }
    else if (rr < 0.185) { kind = 2; }
    else if (rr < 0.52) { const q = cell(0.185, 0.52, N, 1.7); dcell = q.d; cid = 262 + q.li + sd * 7; }
    else if (rr < 0.565) { kind = 2; }
    else if (rr < 1.0) { const q = cell(0.565, 1.0, 2 * N, 1.05); dcell = q.d; cid = 393 + q.li + sd * 7; }
    else if (rr < 1.07) { kind = 2; }
    else { kind = 0; }

    // classify glass vs leading within a foil band
    let glassBri = 0, edge = 0;
    if (dcell < 1.5 && kind !== 2 && rr < 1.0) {
      if (dcell < glassThresh) { kind = 1; glassBri = 1 - dcell * 0.42; }
      else if (dcell < 1.0) { kind = 2; edge = 1 - (dcell - glassThresh) / (1.0 - glassThresh); }
      else { kind = 0; }
    }

    // colour
    let H, Sv, Bv;
    if (kind === 1) {
      // stained glass, backlit
      let jh = jhue(cid);
      Bv = glassBri * back * expo;
      Sv = 0.9;
      if (style === 'art-nouveau') { Sv = 0.52; Bv *= 1.08; }
      else if (style === 'neon-glass') { Sv = 0.96; Bv *= 1.2; }
      else if (style === 'sunset-backlit') {
        const tt = Math.max(0, Math.min(1, uy + 0.55));
        jh = 300 - 278 * tt; Sv = 0.82; Bv *= 1.05;
      } else if (style === 'mono-tracery') { jh = 210; Sv = 0.18; Bv = 0.07 + glassBri * 0.05; }
      H = jh + P.hue + secHue;
    } else if (kind === 2) {
      // stone leading / mullions
      if (style === 'mono-tracery') { H = 205; Sv = 0.08; Bv = 0.30 + edge * 0.55; }
      else if (style === 'neon-glass') { H = 250; Sv = 0.5; Bv = 0.02 + edge * 0.05; }
      else if (style === 'art-nouveau') { H = 45 + P.hue; Sv = 0.45; Bv = (0.14 + edge * 0.22) * (0.6 + 0.4 * back); }
      else if (style === 'sunset-backlit') { H = 24 + P.hue; Sv = 0.5; Bv = (0.10 + edge * 0.16) * (0.6 + 0.5 * back); }
      else { H = 28 + P.hue; Sv = 0.35; Bv = (0.11 + edge * 0.20) * (0.55 + 0.45 * back); }
    } else {
      // ambient beyond the window: dark stone with faint backlight bleed (keeps luminance, no hard black ring)
      const halo = Math.exp(-(rr - 1.0) * 3.2) * 0.5;
      if (style === 'mono-tracery') { H = 210; Sv = 0.2; Bv = 0.04 + halo * 0.05; }
      else if (style === 'sunset-backlit') { H = 18; Sv = 0.6; Bv = 0.05 + (halo + 0.02) * back * 0.7; }
      else if (style === 'neon-glass') { H = 255; Sv = 0.7; Bv = 0.03 + halo * 0.06; }
      else if (style === 'art-nouveau') { H = 40; Sv = 0.35; Bv = 0.07 + halo * back * 0.5; }
      else { H = 225; Sv = 0.5; Bv = 0.05 + halo * back * 0.6; }
    }

    // bloom: clamp bright & desaturate the hottest cores for a backlit glow
    let vraw = Bv; const bloom = Math.max(0, vraw - 1);
    Bv = Math.min(1, vraw); Sv = Math.max(0, Sv * (1 - bloom * 0.55));
    const rgb = hsb2rgb(H, Sv, Bv);
    const o = 4 * (j * BW + i);
    px[o] = rgb[0] * 255; px[o + 1] = rgb[1] * 255; px[o + 2] = rgb[2] * 255; px[o + 3] = 255;
  }
}
